// ── shared: llm-wiki MCP client (Streamable HTTP) + Slack notify ─────────────
// Prepended to archive.js / compile.js by n8n/build.py. Runs inside an n8n Code
// node (task runner), so only `this.helpers.httpRequest` and $env are available.
const mcpUrl = $env.LLM_WIKI_MCP_URL;
const bearer = $env.LLM_WIKI_MCP_BEARER_TOKEN;
if (!mcpUrl || !bearer) throw new Error('LLM_WIKI_MCP_URL / LLM_WIKI_MCP_BEARER_TOKEN not set');
let sessionId = null; let rpcId = 0;
const parse = (res) => {
  const ct = String(res.headers['content-type'] || '');
  const text = typeof res.body === 'string' ? res.body : JSON.stringify(res.body);
  if (ct.includes('text/event-stream')) {
    for (const line of text.split('\n')) if (line.startsWith('data:')) { const d = line.slice(5).trim(); if (d) return JSON.parse(d); }
    throw new Error('SSE without data');
  }
  return text.trim() ? JSON.parse(text) : null;
};
const post = async (payload, expectBody = true) => {
  const headers = { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream', 'Authorization': `Bearer ${bearer}` };
  if (sessionId) headers['Mcp-Session-Id'] = sessionId;
  const res = await this.helpers.httpRequest({ method: 'POST', url: mcpUrl, headers, body: JSON.stringify(payload), returnFullResponse: true, timeout: 120000 });
  const sid = res.headers['mcp-session-id']; if (sid) sessionId = sid;
  if (!expectBody) return null;
  const msg = parse(res);
  if (msg && msg.error) throw new Error(`${payload.method}: ${JSON.stringify(msg.error)}`);
  return msg ? msg.result : null;
};
const call = async (name, args) => {
  const r = await post({ jsonrpc: '2.0', id: ++rpcId, method: 'tools/call', params: { name, arguments: args } });
  const text = (r.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n');
  if (r.isError) throw new Error(`${name} failed: ${text}`);
  try { return JSON.parse(text); } catch { return { text }; }
};
const mcpInit = async () => {
  await post({ jsonrpc: '2.0', id: ++rpcId, method: 'initialize', params: { protocolVersion: '2025-03-26', capabilities: {}, clientInfo: { name: 'n8n-wiki-ingest', version: '2' } } });
  await post({ jsonrpc: '2.0', method: 'notifications/initialized' }, false);
};
const notify = async (msg) => {
  const slack = $env.WIKI_SLACK_WEBHOOK_URL || '';
  if (!slack) return;
  try { await this.helpers.httpRequest({ method: 'POST', url: slack, body: JSON.stringify({ text: msg }), headers: { 'Content-Type': 'application/json' }, timeout: 10000 }); } catch (e) { /* fail-open */ }
};
// ── wiki-ingest-raw / step 1: preserve the original ──────────────────────────
// Input (from the calling workflow, one item):
//   rawPath   raw/meetings/<source>-<date>-<slug>      (slug already built)
//   title, date (YYYY-MM-DD), heldAt (ISO+09:00), meetingType, source, sourceRef
//   frontmatter  optional extra scalar fields for the page header
//   body      the transcript / notes text
// Deterministic and must succeed; compilation is best-effort afterwards.
const it = $input.first().json;
for (const k of ['rawPath', 'title', 'date', 'body', 'source']) if (!it[k]) throw new Error(`ingest input lacks ${k}`);
if (!/^raw\//.test(it.rawPath)) throw new Error(`rawPath must live under raw/: ${it.rawPath}`);
const q = (s) => JSON.stringify(String(s));
const extra = Object.entries(it.frontmatter || {}).filter(([, v]) => v !== null && v !== undefined && v !== '')
  .map(([k, v]) => `${k}: ${typeof v === 'number' ? v : q(v)}`);
const fm = [
  '---',
  `title: ${q(it.title)}`,
  'type: raw',
  'source_type: meetings',
  `date: ${it.date}`,
  it.heldAt ? `held_at: ${q(it.heldAt)}` : null,
  `meeting_type: ${it.meetingType || 'planning'}`,
  `source: ${it.source}`,
  it.sourceRef ? `source_ref: ${q(it.sourceRef)}` : null,
  ...extra,
  `managed_by: n8n-${it.source}-ingest`,
  '---',
].filter(Boolean).join('\n');
const intro = it.note || `${it.source} 자동 수집 원문 (${it.heldAt || it.date}). 원문은 수정하지 않는다 — 정정은 wiki/ 페이지에서.`;
const content = `${fm}\n\n# ${it.title}\n\n> ${intro}\n\n${String(it.body).trim()}\n`;

await mcpInit();
// Redelivery and reruns are normal (Webex resends, Slack edits the same
// message several times): an already-preserved original is success, and
// preserved sources are create-only anyway.
let archive; let alreadyArchived = false;
try { await call('wiki_content_read', { uri: it.rawPath }); alreadyArchived = true; archive = { skipped: 'already archived' }; } catch (e) { /* not there yet */ }
if (!alreadyArchived) {
  archive = await call('wiki_apply', { mode: 'archive', changes: [{ path: it.rawPath, content }], message: `archive(${it.source}): ${it.title} ${it.date}` });
}
return [{ json: { ...it, body: undefined, bodyChars: String(it.body).length, alreadyArchived, archive } }];

